create extension if not exists pgcrypto;
create table if not exists public.friend_groups(id uuid primary key default gen_random_uuid(),name text not null,invite_hash text not null,created_at timestamptz not null default now());
create table if not exists public.friend_members(group_id uuid not null references public.friend_groups(id) on delete cascade,user_id uuid not null,display_name text not null check(char_length(display_name) between 1 and 30),joined_at timestamptz not null default now(),primary key(group_id,user_id));
create table if not exists public.friend_locations(group_id uuid not null references public.friend_groups(id) on delete cascade,user_id uuid not null,lat double precision,lng double precision,accuracy double precision,sharing_enabled boolean not null default false,updated_at timestamptz not null default now(),primary key(group_id,user_id));
alter table public.friend_groups enable row level security; alter table public.friend_members enable row level security; alter table public.friend_locations enable row level security;
revoke all on public.friend_groups from anon,authenticated; revoke all on public.friend_members from anon; revoke all on public.friend_locations from anon;
grant select,update on public.friend_members to authenticated; grant select,insert,update,delete on public.friend_locations to authenticated;
create or replace function public.is_friend_group_member(g uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.friend_members where group_id=g and user_id=auth.uid()); $$;
revoke all on function public.is_friend_group_member(uuid) from public; grant execute on function public.is_friend_group_member(uuid) to authenticated;
drop policy if exists "members see members" on public.friend_members; create policy "members see members" on public.friend_members for select to authenticated using(public.is_friend_group_member(group_id));
drop policy if exists "members update own name" on public.friend_members; create policy "members update own name" on public.friend_members for update to authenticated using(user_id=auth.uid() and public.is_friend_group_member(group_id)) with check(user_id=auth.uid() and public.is_friend_group_member(group_id));
drop policy if exists "members see group locations" on public.friend_locations; create policy "members see group locations" on public.friend_locations for select to authenticated using(public.is_friend_group_member(group_id) and (user_id=auth.uid() or sharing_enabled=true));
drop policy if exists "members insert own location" on public.friend_locations; create policy "members insert own location" on public.friend_locations for insert to authenticated with check(user_id=auth.uid() and public.is_friend_group_member(group_id));
drop policy if exists "members update own location" on public.friend_locations; create policy "members update own location" on public.friend_locations for update to authenticated using(user_id=auth.uid() and public.is_friend_group_member(group_id)) with check(user_id=auth.uid() and public.is_friend_group_member(group_id));
drop policy if exists "members delete own location" on public.friend_locations; create policy "members delete own location" on public.friend_locations for delete to authenticated using(user_id=auth.uid() and public.is_friend_group_member(group_id));
create or replace function public.join_friend_group(invite_code text,nickname text) returns uuid language plpgsql security definer set search_path=public as $$ declare g uuid; n text; begin if auth.uid() is null then raise exception 'Niet ingelogd'; end if; n:=btrim(nickname); if char_length(n)<1 or char_length(n)>30 then raise exception 'Ongeldige naam'; end if; select id into g from public.friend_groups where invite_hash=crypt(invite_code,invite_hash) limit 1; if g is null then raise exception 'Onjuiste groepscode'; end if; insert into public.friend_members(group_id,user_id,display_name) values(g,auth.uid(),n) on conflict(group_id,user_id) do update set display_name=excluded.display_name; insert into public.friend_locations(group_id,user_id,sharing_enabled) values(g,auth.uid(),false) on conflict(group_id,user_id) do nothing; return g; end; $$;
revoke all on function public.join_friend_group(text,text) from public; grant execute on function public.join_friend_group(text,text) to authenticated;
insert into public.friend_groups(name,invite_hash) select 'Kermisvrienden',crypt('MIJN-GEHEIME-KERMISCODE',gen_salt('bf')) where not exists(select 1 from public.friend_groups where name='Kermisvrienden');
do $$ begin alter publication supabase_realtime add table public.friend_locations; exception when duplicate_object then null; end $$;
do $$ begin alter publication supabase_realtime add table public.friend_members; exception when duplicate_object then null; end $$;
